import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

// Import Bootstrap & Font Awesome (already installed)
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

export default function Register() {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    // Basic validation
    if (password.length < 6) {
      alert('Password must be at least 6 characters');
      setLoading(false);
      return;
    }

    try {
      const res = await axios.post('http://localhost:5000/api/auth/register', {
        name,
        email,
        password
      });
      
      // Save token and redirect
      localStorage.setItem('token', res.data.token);
      axios.defaults.headers.common['Authorization'] = `Bearer ${res.data.token}`;
      navigate('/quizzes');
    } catch (err) {
      const errorMsg = err.response?.data?.error || 'Registration failed. Email may already exist.';
      alert(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="register-container" style={{ 
      margin: 0, 
      padding: 0, 
      height: '100vh', 
      background: '#60a3bc' 
    }}>
      <div className="d-flex justify-content-center align-items-center h-100">
        <div className="user_card" style={{
          height: '480px', // Slightly taller for extra field
          width: '350px',
          background: '#f39c12',
          position: 'relative',
          display: 'flex',
          justifyContent: 'center',
          flexDirection: 'column',
          padding: '10px',
          boxShadow: '0 4px 8px 0 rgba(0,0,0,0.2), 0 6px 20px 0 rgba(0,0,0,0.19)',
          borderRadius: '5px'
        }}>
          <div className="d-flex justify-content-center">
            <div className="brand_logo_container" style={{
              position: 'absolute',
              height: '170px',
              width: '170px',
              top: '-75px',
              borderRadius: '50%',
              background: '#60a3bc',
              padding: '10px',
              textAlign: 'center'
            }}>
              {/* 👇 Quiz-themed icon (replace with your own) */}
              <img 
                src="/logo.png" 
                className="brand_logo" 
                alt="Quiz Logo"
                style={{
                  height: '150px',
                  width: '150px',
                  borderRadius: '50%',
                  border: '2px solid white'
                }}
              />
            </div>
          </div>

          <div className="d-flex justify-content-center form_container" style={{ marginTop: '100px' }}>
            <form onSubmit={handleSubmit} style={{ width: '100%' }}>
              {/* 👇 Name Field */}
              <div className="input-group mb-3">
                <div className="input-group-append">
                  <span className="input-group-text" style={{ 
                    background: '#c0392b', 
                    color: 'white', 
                    border: '0', 
                    borderRadius: '0.25rem 0 0 0.25rem' 
                  }}>
                    <i className="fas fa-user"></i>
                  </span>
                </div>
                <input
                  type="text"
                  className="form-control input_user"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Full Name"
                  required
                  style={{ boxShadow: 'none', outline: '0px' }}
                />
              </div>

              {/* 👇 Email Field */}
              <div className="input-group mb-3">
                <div className="input-group-append">
                  <span className="input-group-text" style={{ 
                    background: '#c0392b', 
                    color: 'white', 
                    border: '0', 
                    borderRadius: '0.25rem 0 0 0.25rem' 
                  }}>
                    <i className="fas fa-envelope"></i>
                  </span>
                </div>
                <input
                  type="email"
                  className="form-control input_user"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Email"
                  required
                  style={{ boxShadow: 'none', outline: '0px' }}
                />
              </div>

              {/* 👇 Password Field */}
              <div className="input-group mb-2">
                <div className="input-group-append">
                  <span className="input-group-text" style={{ 
                    background: '#c0392b', 
                    color: 'white', 
                    border: '0', 
                    borderRadius: '0.25rem 0 0 0.25rem' 
                  }}>
                    <i className="fas fa-key"></i>
                  </span>
                </div>
                <input
                  type="password"
                  className="form-control input_pass"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Password (min 6 chars)"
                  required
                  style={{ boxShadow: 'none', outline: '0px' }}
                />
              </div>

              <div className="d-flex justify-content-center mt-3 login_container" style={{ padding: '0 2rem' }}>
                <button 
                  type="submit" 
                  className="btn login_btn" 
                  disabled={loading}
                  style={{ 
                    width: '100%', 
                    background: '#c0392b', 
                    color: 'white' 
                  }}
                >
                  {loading ? 'Registering...' : 'Register'}
                </button>
              </div>
            </form>
          </div>

          <div className="mt-3 text-center">
            <div className="links">
              Already have an account?{' '}
              <a href="/login" className="ml-2" style={{ color: '#fff', textDecoration: 'underline' }}>
                Login
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
